package ru.fastgo.tsd;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import org.json.*;
import java.util.*;
public final class LocalStore extends SQLiteOpenHelper {
 public LocalStore(Context c){super(c,"fastgo-tsd-v1.db",null,1);setWriteAheadLoggingEnabled(true);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE kv (k TEXT PRIMARY KEY,v TEXT NOT NULL)");db.execSQL("CREATE TABLE docs (id TEXT PRIMARY KEY,kind TEXT NOT NULL,v TEXT NOT NULL)");db.execSQL("CREATE TABLE catalog (id TEXT PRIMARY KEY,barcode TEXT,sku TEXT,v TEXT NOT NULL)");db.execSQL("CREATE INDEX catalog_barcode ON catalog(barcode)");db.execSQL("CREATE INDEX catalog_sku ON catalog(sku)");}
 public void onUpgrade(SQLiteDatabase d,int old,int n){throw new IllegalStateException("Неизвестная версия локальной базы");}
 public synchronized String get(String k){try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM kv WHERE k=?",new String[]{k})){return c.moveToFirst()?c.getString(0):"";}}
 public synchronized void put(String k,String v){ContentValues x=new ContentValues();x.put("k",k);x.put("v",v);getWritableDatabase().insertWithOnConflict("kv",null,x,SQLiteDatabase.CONFLICT_REPLACE);}
 public synchronized JSONObject doc(String id)throws JSONException{try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM docs WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 public synchronized void save(JSONObject d)throws JSONException{ContentValues v=new ContentValues();v.put("id",d.getString("id"));v.put("kind",d.getString("kind"));v.put("v",d.toString());if(getWritableDatabase().insertWithOnConflict("docs",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new IllegalStateException("Не удалось сохранить скан");}
 public synchronized JSONObject open(String kind)throws JSONException{String id=get("current:"+kind);JSONObject d=id.isEmpty()?null:doc(id);if(d==null||!d.optString("state").equals("open")){d=ScanDocument.create(kind);save(d);put("current:"+kind,d.getString("id"));}return d;}
 public synchronized List<JSONObject> pending()throws JSONException{List<JSONObject> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM docs",null)){while(c.moveToNext()){JSONObject d=new JSONObject(c.getString(0));if(d.optString("state").equals("open"))out.add(d);}}return out;}
 public synchronized int blockingDocuments()throws JSONException{int count=0;for(JSONObject doc:pending())if(ScanDocument.count(doc)>0||doc.optBoolean("cancel_requested")||"processing".equals(get("server:"+doc.getString("id"))))count++;return count;}
 public synchronized JSONObject match(String code)throws JSONException{String q=code.trim().toUpperCase(Locale.ROOT);String alias=get("alias:"+q);if(!alias.isEmpty()){JSONObject known=part(alias);if(known!=null)return known;}try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM catalog WHERE upper(barcode)=? OR upper(sku)=? OR upper(id)=?",new String[]{q,q,q})){if(!c.moveToFirst())return null;JSONObject p=new JSONObject(c.getString(0));if(c.moveToNext())throw new IllegalStateException("Код принадлежит нескольким товарам");return p;}}
 public synchronized JSONObject part(String id)throws JSONException{try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM catalog WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 public synchronized void catalog(JSONArray a)throws JSONException{SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.delete("catalog",null,null);for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);if(!p.optBoolean("active",true))continue;ContentValues v=new ContentValues();v.put("id",p.getString("id"));v.put("barcode",p.optString("barcode"));v.put("sku",p.optString("sku"));v.put("v",p.toString());if(db.insert("catalog",null,v)<0)throw new IllegalStateException("Ошибка каталога");}put("catalog_at",Long.toString(System.currentTimeMillis()));db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public synchronized void scan(String docId,String code)throws JSONException{JSONObject d=doc(docId);if(d.optString("kind").equals("parts"))ScanDocument.clearPickup(d);d.remove("scan_error");ScanDocument.append(d,code,match(code));ScanDocument.items(d);save(d);}
 public synchronized void selectPickup(String id,String code)throws JSONException{JSONObject d=doc(id);ScanDocument.selectPickup(d,code);save(d);}
 public synchronized void pickupResult(JSONObject selected,JSONObject quote,String error,boolean permanent,long retryAt)throws JSONException{JSONObject current=doc(selected.getString("id"));if(!ScanDocument.samePickup(current,selected))return;if(quote!=null){if(quote.optString("id").isEmpty()||quote.optString("master_id").isEmpty())throw new JSONException("Сервер не подтвердил ремонт и мастера");String code=quote.optString("code",selected.getString("pickup_scan"));if(!ScanDocument.isPickupCode(code))throw new JSONException("Сервер не подтвердил код выдачи");current.put("pickup",quote).put("pickup_code",code);current.remove("pickup_error");current.remove("pickup_retry_at");current.remove("pickup_blocked");}else{current.put("pickup_error",error).put("pickup_blocked",permanent).put("pickup_retry_at",retryAt).put("pickup_attempts",current.optInt("pickup_attempts")+1);}save(current);}
 public synchronized void scanError(String id,String message)throws JSONException{JSONObject current=doc(id);if(current!=null&&current.optString("state").equals("open")){current.put("scan_error",message);save(current);}}
 public synchronized void cancelScan(String docId,String eventId)throws JSONException{JSONObject d=doc(docId);if(d==null||!d.optString("state").equals("open"))return;JSONArray events=d.getJSONArray("events");for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);if(e.getString("id").equals(eventId)&&!e.optBoolean("undone")){e.put("undone",true);d.put("revision",d.getInt("revision")+1);save(d);return;}}}
 public synchronized void undo(String id)throws JSONException{JSONObject d=doc(id);if(d.optString("kind").equals("parts"))ScanDocument.clearPickup(d);d.remove("scan_error");if(ScanDocument.undo(d))save(d);}
 public synchronized void requestCancel(String id)throws JSONException{JSONObject d=doc(id);if(d!=null&&d.optString("state").equals("open")){d.put("cancel_requested",true);save(d);}}
 public synchronized void acceptReceipt(String id,JSONArray quantities,int revision)throws JSONException{JSONObject d=doc(id);if(d==null||d.optInt("revision")!=revision)throw new IllegalStateException("Приход изменился. Проверьте количество ещё раз");ScanDocument.acceptReceipt(d,quantities);save(d);}
 public synchronized void acknowledge(String id,int revision)throws JSONException{JSONObject d=doc(id);if(d!=null){d.put("acked",Math.max(d.optInt("acked"),revision));save(d);}}
 public synchronized void complete(String id,int revision)throws JSONException{JSONObject d=doc(id);if(d==null||!d.optString("state").equals("open"))return;JSONObject next=d.optBoolean("cancel_requested")||d.getString("kind").equals("repair")?ScanDocument.create(d.getString("kind")):ScanDocument.afterCommit(d,revision);d.put("state","done");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{save(d);save(next);put("current:"+d.getString("kind"),next.getString("id"));if(id.equals(get("active_document")))put("active_document","");db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public synchronized void resolve(String docId,String eventId,JSONObject p)throws JSONException{JSONObject d=doc(docId);if(d==null)return;put("alias:"+p.optString("barcode"),p.getString("id"));JSONArray events=d.getJSONArray("events");for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);if(e.getString("id").equals(eventId)&&!e.has("part_id")){put("alias:"+e.getString("code").toUpperCase(Locale.ROOT),p.getString("id"));ContentValues row=new ContentValues();row.put("id",p.getString("id"));row.put("barcode",p.optString("barcode"));row.put("sku",p.optString("sku"));row.put("v",p.toString());getWritableDatabase().insertWithOnConflict("catalog",null,row,SQLiteDatabase.CONFLICT_REPLACE);d.put("revision",d.getInt("revision")+1);e.put("revision",d.getInt("revision")).put("part_id",p.getString("id")).put("name",p.getString("name")).put("price",p.optDouble("retail_price",0));save(d);return;}}}
}
